package com.agacostays.payroll.controller; import com.agacostays.payroll.dto.request.*;import com.agacostays.payroll.dto.response.*;import com.agacostays.payroll.security.CurrentUserProvider;import com.agacostays.payroll.service.PayrollService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/manager/hotel-branches/{branchId}/payroll") public class BranchPayrollController{final PayrollService s;final CurrentUserProvider c;public BranchPayrollController(PayrollService s,CurrentUserProvider c){this.s=s;this.c=c;}@PostMapping("/generate") public ResponseEntity<ApiResponse<java.util.List<PayrollResponse>>> gen(@PathVariable Long branchId,@Valid @RequestBody GeneratePayrollRequest r){return ResponseEntity.ok(ApiResponse.ok("Branch payroll generated",s.generate(new GeneratePayrollRequest(branchId,r.month(),r.year(),r.staffId(),r.paymentMode()),c.userId())));}@PostMapping("/credit-salaries") public ResponseEntity<ApiResponse<java.util.List<SalaryCreditResponse>>> credit(@PathVariable Long branchId,@RequestParam int month,@RequestParam int year,@Valid @RequestBody CreditSalaryRequest r){return ResponseEntity.ok(ApiResponse.ok("Branch salaries credited",s.creditAll(month,year,r.paymentMode(),c.userId())));}@GetMapping public ResponseEntity<ApiResponse<PageResponse<PayrollResponse>>> list(@PathVariable Long branchId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ResponseEntity.ok(ApiResponse.ok("Branch payroll fetched",s.branchPayroll(branchId,page,size)));}@GetMapping("/report") public ResponseEntity<ApiResponse<PageResponse<PayrollResponse>>> report(@PathVariable Long branchId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ResponseEntity.ok(ApiResponse.ok("Branch payroll report",s.branchPayroll(branchId,page,size)));}}
